// LOCATION PING HANDLER v1.0.0 (two-driver reset)
// Driver identity comes from the SECRET, not a spoofable driver field.
// Storage upgraded from data.location -> data.locations_by_driver[driver].
// Env: CONCIERGE_PING_SECRET_T, CONCIERGE_PING_SECRET_FISTON

var SECRET_T = $env.CONCIERGE_PING_SECRET_T;
var SECRET_FISTON = $env.CONCIERGE_PING_SECRET_FISTON;

var data = $getWorkflowStaticData('global');
if (!data.initialized) {
  data.locations_by_driver = {};
  data.ping_log = [];
  data.initialized = true;
}
if (!data.locations_by_driver) { data.locations_by_driver = {}; }
if (!data.ping_log) { data.ping_log = []; }

var body = $json.body || $json;
var nowTs = Math.floor(Date.now() / 1000);

// secret -> driver (identity by secret; any body.driver is ignored on the ping path)
var secretMap = {};
if (SECRET_T) { secretMap[SECRET_T] = 'T'; }
if (SECRET_FISTON) { secretMap[SECRET_FISTON] = 'FISTON'; }

var driver = (body && body.auth != null) ? secretMap[body.auth] : undefined;

if (!driver) {
  data.ping_log.push({ ts: nowTs, status: 'rejected_auth' });
  if (data.ping_log.length > 100) { data.ping_log = data.ping_log.slice(-100); }
  return [{ json: { status: 401, body: { ok: false, error: 'unauthorized' } } }];
}

var lat = parseFloat(body.lat);
var lng = parseFloat(body.lng);
if (isNaN(lat) || isNaN(lng)) {
  data.ping_log.push({ ts: nowTs, status: 'rejected_payload', driver: driver, reason: 'bad_coords' });
  if (data.ping_log.length > 100) { data.ping_log = data.ping_log.slice(-100); }
  return [{ json: { status: 400, body: { ok: false, error: 'bad coordinates' } } }];
}
if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
  data.ping_log.push({ ts: nowTs, status: 'rejected_payload', driver: driver, reason: 'coords_out_of_range' });
  if (data.ping_log.length > 100) { data.ping_log = data.ping_log.slice(-100); }
  return [{ json: { status: 400, body: { ok: false, error: 'coordinates out of range' } } }];
}

var source = (body.source || 'unknown').toString().toLowerCase();
if (['iphone', 'watch', 'manual', 'shortcut'].indexOf(source) === -1) { source = 'unknown'; }

var previousLocation = data.locations_by_driver[driver] || null;
var ageSinceLastPing = previousLocation ? (nowTs - previousLocation.ts) : null;

data.locations_by_driver[driver] = { lat: lat, lng: lng, ts: nowTs, source: source, driver: driver, notification_count: 0 };

data.ping_log.push({ ts: nowTs, status: 'accepted', driver: driver, source: source, age_since_last: ageSinceLastPing });
if (data.ping_log.length > 100) { data.ping_log = data.ping_log.slice(-100); }

return [{ json: {
  status: 200,
  body: { ok: true, driver: driver, received_at: nowTs, age_since_last: ageSinceLastPing, location: { lat: lat, lng: lng, source: source } }
} }];

// ETA REQUEST NORMALIZER v1.0.0 (two-driver reset)
// Validates the shared dispatch secret (consumer-side), accepts an address,
// and an optional driver selector ('T' | 'FISTON', default 'T').
// Env: CONCIERGE_DISPATCH_SHARED_SECRET

var SHARED_SECRET = $env.CONCIERGE_DISPATCH_SHARED_SECRET;
var DRIVERS = ['T', 'FISTON'];

var body = $json.body || $json;
var auth = body.auth;
var address = body.address;

if (!SHARED_SECRET || auth !== SHARED_SECRET) {
  return [{ json: { ok: false, short_circuit: true, error: 'unauthorized', _http_status: 401 } }];
}
if (!address || !address.toString().trim()) {
  return [{ json: { ok: false, short_circuit: true, error: 'no address provided', _http_status: 400 } }];
}

var driver = (body.driver || 'T').toString().trim().toUpperCase();
if (DRIVERS.indexOf(driver) === -1) {
  return [{ json: { ok: false, short_circuit: true, error: 'unknown driver \"' + driver + '\" (expected T or FISTON)', _http_status: 400 } }];
}

return [{ json: { address: address.toString().trim(), driver: driver } }];

// ETA REQUEST BUILDER v1.0.0 (two-driver reset)
// Reads data.locations_by_driver[driver] + caller address. Google key from env.
// Env: GOOGLE_MAPS_API_KEY

var GOOGLE_API_KEY = $env.GOOGLE_MAPS_API_KEY;
var data = $getWorkflowStaticData('global');
if (!data.locations_by_driver) { data.locations_by_driver = {}; }

var input = $json;

// Pass through short-circuits from upstream (webhook auth failures, etc).
if (input.short_circuit === true) {
  return [{ json: input }];
}

var address = (input.address || '').toString().trim();
var driver = (input.driver || 'T').toString().trim().toUpperCase();
var nowTs = Math.floor(Date.now() / 1000);

if (!address) {
  return [{ json: { ok: false, error: 'no address provided', short_circuit: true } }];
}
if (!GOOGLE_API_KEY) {
  return [{ json: { ok: false, error: 'google api key not configured', short_circuit: true } }];
}

var loc = data.locations_by_driver[driver];
if (!loc) {
  return [{ json: { ok: false, error: 'no location ping yet for driver ' + driver + ' -- tap concierge ping on phone', short_circuit: true } }];
}

var locationAgeSec = nowTs - loc.ts;
var locationStale = locationAgeSec > 900;

var destAddress = address;
if (!/montreal|laval|brossard|quebec|qc|montréal/i.test(destAddress)) {
  destAddress = destAddress + ', Montreal, QC, Canada';
}

var url = 'https://maps.googleapis.com/maps/api/distancematrix/json' +
  '?origins=' + loc.lat + ',' + loc.lng +
  '&destinations=' + encodeURIComponent(destAddress) +
  '&mode=driving' +
  '&departure_time=now' +
  '&units=metric' +
  '&region=ca' +
  '&key=' + GOOGLE_API_KEY;

return [{ json: {
  ok: true,
  short_circuit: false,
  url: url,
  driver: driver,
  address_input: address,
  address_resolved: destAddress,
  origin: { lat: loc.lat, lng: loc.lng, source: loc.source, driver: driver },
  location_age_seconds: locationAgeSec,
  location_stale: locationStale,
  requested_at: nowTs
} }];

// ETA RESPONSE PARSER v1.0.0 (two-driver reset)
// Response contract preserved from the old core; only `driver` is added.

var BUFFER_MIN = 5;

var response = $json;
var buildCtx = $('Build ETA Request1').item.json;
if (response.status !== 'OK') {
  return [{ json: { ok: false, error: 'google_api_error', google_status: response.status, google_message: response.error_message || null } }];
}
if (!response.rows || !response.rows[0] || !response.rows[0].elements || !response.rows[0].elements[0]) {
  return [{ json: { ok: false, error: 'malformed_google_response', raw: response } }];
}
var element = response.rows[0].elements[0];
if (element.status !== 'OK') {
  return [{ json: { ok: false, error: 'no_route_found', element_status: element.status, address_tried: buildCtx.address_resolved } }];
}
var etaSeconds = (element.duration_in_traffic && element.duration_in_traffic.value) ? element.duration_in_traffic.value : element.duration.value;
var etaMinutes = Math.round(etaSeconds / 60);
var distanceMeters = element.distance.value;
var distanceKm = Math.round((distanceMeters / 1000) * 10) / 10;
var nowTs = Math.floor(Date.now() / 1000);
var arrivalTs = nowTs + etaSeconds;
var arrivalDate = new Date(arrivalTs * 1000);

var clientEtaMinutes = etaMinutes + BUFFER_MIN;
var clientArrivalDate = new Date((arrivalTs + BUFFER_MIN * 60) * 1000);

function formatArrivalLabel(d) {
  var fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Toronto', hour: 'numeric', minute: '2-digit', hour12: true });
  return fmt.format(d).toLowerCase().replace(/\s/g, '');
}
var arrivalLabel = formatArrivalLabel(arrivalDate);
var arrivalIso = arrivalDate.toISOString();
var clientArrivalLabel = formatArrivalLabel(clientArrivalDate);
var clientArrivalIso = clientArrivalDate.toISOString();

var origin = buildCtx.origin;
var mapsUrl = 'https://www.google.com/maps/dir/?api=1' +
  '&origin=' + origin.lat + ',' + origin.lng +
  '&destination=' + encodeURIComponent(buildCtx.address_resolved) +
  '&travelmode=driving';
return [{ json: {
  ok: true,
  driver: buildCtx.driver,
  eta_seconds: etaSeconds,
  eta_minutes: etaMinutes,
  distance_km: distanceKm,
  distance_text: element.distance.text,
  duration_text: (element.duration_in_traffic && element.duration_in_traffic.text) || element.duration.text,
  arrival_iso: arrivalIso,
  arrival_label: arrivalLabel,
  client_eta_minutes: clientEtaMinutes,
  client_arrival_iso: clientArrivalIso,
  client_arrival_label: clientArrivalLabel,
  buffer_minutes: BUFFER_MIN,
  maps_url: mapsUrl,
  origin: origin,
  address_input: buildCtx.address_input,
  address_resolved: buildCtx.address_resolved,
  location_age_seconds: buildCtx.location_age_seconds,
  location_stale: buildCtx.location_stale,
  calculated_at: nowTs
} }];
